import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline
_cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAException.h>
#include <cstdint>
#include <limits>
__device__ __forceinline__ float gelu_tanh_scalar(float v) {
    const float v3 = v * v * v;
    const float inner = 0.79788456080286535588f * (v + 0.044715f * v3);
    const float e = __expf(2.0f * inner);
    const float t = 1.0f - __fdividef(2.0f, e + 1.0f);
    return 0.5f * v * (1.0f + t);
}
__global__ void __launch_bounds__(256) gelu_tanh_vec4_kernel(const float4* __restrict__ x,
                                      float4* __restrict__ y,
                                      int64_t n4) {
    const int64_t stride = static_cast<int64_t>(gridDim.x) * blockDim.x * 2;
    for (int64_t i = (static_cast<int64_t>(blockIdx.x) * blockDim.x + threadIdx.x) * 2; i < n4; i += stride) {
        float4 a = __ldcs(x + i);
        const bool has2 = (i + 1) < n4;
        float4 b;
        if (has2) {
            b = __ldcs(x + (i + 1));
        }
        float4 r;
        r.x = gelu_tanh_scalar(a.x);
        r.y = gelu_tanh_scalar(a.y);
        r.z = gelu_tanh_scalar(a.z);
        r.w = gelu_tanh_scalar(a.w);
        __stcs(y + i, r);
        if (has2) {
            float4 s;
            s.x = gelu_tanh_scalar(b.x);
            s.y = gelu_tanh_scalar(b.y);
            s.z = gelu_tanh_scalar(b.z);
            s.w = gelu_tanh_scalar(b.w);
            __stcs(y + (i + 1), s);
        }
    }
}
__global__ void gelu_tanh_tail_kernel(const float* __restrict__ x,
                                      float* __restrict__ y,
                                      int64_t start,
                                      int64_t n) {
    const int64_t idx = start + static_cast<int64_t>(blockIdx.x) * blockDim.x + threadIdx.x;
    if (idx < n) {
        __stcs(y + idx, gelu_tanh_scalar(__ldcs(x + idx)));
    }
}
torch::Tensor gelu_cuda(torch::Tensor x) {
    TORCH_CHECK(x.is_cuda(), "gelu_cuda expects a CUDA tensor");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "gelu_cuda expects float32");
    auto x_contig = x.contiguous();
    auto y = torch::empty_like(x_contig);
    const int64_t n = x_contig.numel();
    if (n == 0) {
        return y;
    }
    const int threads = 256;
    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    const int64_t n4 = n >> 2;
    if (n4 > 0) {
        const int64_t pairs64 = (n4 + 1) >> 1;
        const int64_t blocks64 = (pairs64 + threads - 1) / threads;
        int dev = 0;
        C10_CUDA_CHECK(cudaGetDevice(&dev));
        int num_sms = 0;
        C10_CUDA_CHECK(cudaDeviceGetAttribute(&num_sms, cudaDevAttrMultiProcessorCount, dev));
        const int64_t max_grid = static_cast<int64_t>(num_sms) * 8;
        int64_t grid64 = blocks64 < max_grid ? blocks64 : max_grid;
        if (grid64 > 2147483647LL) {
            grid64 = 2147483647LL;
        }
        const dim3 blocks(static_cast<unsigned int>(grid64));
        gelu_tanh_vec4_kernel<<<blocks, threads, 0, stream>>>(
            reinterpret_cast<const float4*>(x_contig.data_ptr<float>()),
            reinterpret_cast<float4*>(y.data_ptr<float>()),
            n4
        );
        C10_CUDA_KERNEL_LAUNCH_CHECK();
    }
    const int64_t rem = n - (n4 << 2);
    if (rem > 0) {
        const dim3 tblocks(static_cast<unsigned int>((rem + threads - 1) / threads));
        gelu_tanh_tail_kernel<<<tblocks, threads, 0, stream>>>(
            x_contig.data_ptr<float>(),
            y.data_ptr<float>(),
            n4 << 2,
            n
        );
        C10_CUDA_KERNEL_LAUNCH_CHECK();
    }
    return y;
}
"""
_cpp_src = "torch::Tensor gelu_cuda(torch::Tensor x);"
_gelu_ext = load_inline(
    name="gelu_tanh_ext_v2",
    cpp_sources=_cpp_src,
    cuda_sources=_cuda_src,
    functions=["gelu_cuda"],
    verbose=False,
)
class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()
    def forward(self, x):
        if x.is_cuda and x.dtype == torch.float32 and x.is_contiguous():
            return _gelu_ext.gelu_cuda(x)
        orig_device = x.device
        orig_dtype = x.dtype
        x_in = x.to(device="cuda", dtype=torch.float32).contiguous()
        y = _gelu_ext.gelu_cuda(x_in)
        return y.to(device=orig_device, dtype=orig_dtype)

